package com.hmdp.ai.domain.observability;import java.math.BigDecimal;public final class RunUsageSummary {private final long inputTokens,outputTokens,modelCalls,toolCalls;private final BigDecimal totalCost;public RunUsageSummary(long inputTokens,long outputTokens,long modelCalls,long toolCalls,BigDecimal totalCost){this.inputTokens=inputTokens;this.outputTokens=outputTokens;this.modelCalls=modelCalls;this.toolCalls=toolCalls;this.totalCost=totalCost;}public long getInputTokens(){return inputTokens;}public long getOutputTokens(){return outputTokens;}public long getModelCalls(){return modelCalls;}public long getToolCalls(){return toolCalls;}public BigDecimal getTotalCost(){return totalCost;}}
